/**
 * CSS Pre-generation Utility
 *
 * Triggers CSS generation early (after files are fetched) instead of waiting
 * until HTML shell generation during SSR. This runs in parallel with other
 * initialization work, reducing first-request latency by ~2-3 seconds.
 */
import { serverLogger } from "../../utils/index.js";
import { join } from "../../platform/compat/path/index.js";
import { createFileSystem } from "../../platform/compat/fs.js";
import { acquireCSSGenerationSession, extractCandidatesFromFiles, getProjectCSS, } from "./tailwind-compiler.js";
import { hashCandidates } from "./css-identity.js";
import { createPreparedProjectCSSContext, storePreparedProjectCSS, tryGetPreparedProjectCSS, } from "./prepared-project-css-cache.js";
import { shouldIncludeStylePath, shouldTraverseStyleDirectory, } from "./style-scope-profile.js";
const ArrayPrototypeFind = Array.prototype.find;
const StringPrototypeSlice = String.prototype.slice;
const StringPrototypeEndsWith = String.prototype.endsWith;
const RegExpPrototypeExec = RegExp.prototype.exec;
const ReflectApply = Reflect.apply;
const logger = serverLogger.component("css-pregeneration");
const inFlightPreparedCSSBuilds = new Map();
const SOURCE_EXTENSIONS = [".tsx", ".jsx", ".mdx", ".ts", ".js"];
export async function buildPreparedCSSArtifactFromFiles(options) {
    const { projectDir, files, styleProfile, stylesheet, stylesheetPath, minify = true, } = options;
    const candidates = extractCandidatesFromFiles(files, {
        projectDir,
        styleProfile,
    });
    const session = acquireCSSGenerationSession(minify);
    const resolvedStylesheet = stylesheet ?? findStylesheetFromFiles(files, stylesheetPath) ??
        session.compilationSession.defaultStylesheet;
    return await buildPreparedCSSArtifactFromSnapshot(options, resolvedStylesheet, candidates, session);
}
async function buildPreparedCSSArtifactFromSnapshot(options, resolvedStylesheet, candidates, session) {
    const { projectSlug, projectVersion, styleProfile, minify = true, environment = "preview", buildMode = "production", } = options;
    const result = await getProjectCSS(projectSlug, resolvedStylesheet, candidates, {
        minify,
        environment,
        buildMode,
    }, { generationSession: session });
    const context = createPreparedProjectCSSContext(projectSlug, projectVersion, resolvedStylesheet, styleProfile.hash, {
        cssPipelineIdentity: session.cacheIdentity,
        candidatesHash: hashCandidates(candidates),
        minify,
        environment,
        buildMode,
    });
    await storePreparedProjectCSS(context, { css: result.css, hash: result.hash });
    return {
        css: result.css,
        hash: result.hash,
        candidateCount: candidates.size,
        fromCache: result.fromCache,
        context,
    };
}
export async function collectLocalProjectSourceFiles(options) {
    const fs = options.fs ?? createFileSystem();
    const files = [];
    const scanDir = async (directoryPath) => {
        let entries;
        try {
            entries = fs.readDir(directoryPath);
        }
        catch {
            return;
        }
        for await (const entry of entries) {
            const fullPath = join(directoryPath, entry.name);
            if (entry.isDirectory) {
                if (shouldTraverseStyleDirectory(options.styleProfile, fullPath, options.projectDir)) {
                    await scanDir(fullPath);
                }
                continue;
            }
            if (!entry.isFile)
                continue;
            if (!shouldIncludeStylePath(options.styleProfile, fullPath, options.projectDir))
                continue;
            if (!SOURCE_EXTENSIONS.some((extension) => entry.name.endsWith(extension)))
                continue;
            try {
                files.push({
                    path: fullPath,
                    content: await fs.readTextFile(fullPath),
                });
            }
            catch {
                // ignore unreadable files during warmup
            }
        }
    };
    await scanDir(options.projectDir);
    return files;
}
export async function readLocalProjectStylesheet(projectDir, stylesheetPath, fs = createFileSystem()) {
    const candidatePaths = stylesheetPath ? [stylesheetPath.replace(/^\/+/, "")] : [
        "globals.css",
        "global.css",
        "styles/globals.css",
        "app/globals.css",
        "src/globals.css",
        "src/styles/globals.css",
    ];
    for (const relativePath of candidatePaths) {
        const absolutePath = join(projectDir, relativePath);
        try {
            return await fs.readTextFile(absolutePath);
        }
        catch {
            // keep searching
        }
    }
    return undefined;
}
/**
 * Trigger prepared CSS generation in the background when the artifact is not
 * already cached or currently being built.
 */
export async function warmPreparedCSSArtifactFromFiles(options) {
    const minify = options.minify ?? true;
    const candidates = extractCandidatesFromFiles(options.files, {
        projectDir: options.projectDir,
        styleProfile: options.styleProfile,
    });
    const session = acquireCSSGenerationSession(minify);
    const stylesheet = options.stylesheet ??
        findStylesheetFromFiles(options.files, options.stylesheetPath) ??
        session.compilationSession.defaultStylesheet;
    const context = createPreparedProjectCSSContext(options.projectSlug, options.projectVersion, stylesheet, options.styleProfile.hash, {
        cssPipelineIdentity: session.cacheIdentity,
        candidatesHash: hashCandidates(candidates),
        minify,
        environment: options.environment ?? "preview",
        buildMode: options.buildMode ?? "production",
    });
    if (await tryGetPreparedProjectCSS(context))
        return false;
    if (inFlightPreparedCSSBuilds.has(context.cacheKey))
        return false;
    const task = buildPreparedCSSArtifactFromSnapshot({ ...options, stylesheet }, stylesheet, candidates, session).then(() => {
        logger.debug("Warm prepared CSS complete", {
            projectSlug: options.projectSlug,
            projectVersion: options.projectVersion,
            cacheKey: context.cacheKey,
        });
    }).catch((error) => {
        logger.debug("Warm prepared CSS failed", {
            projectSlug: options.projectSlug,
            projectVersion: options.projectVersion,
            cacheKey: context.cacheKey,
            error: error instanceof Error ? error.message : String(error),
        });
    }).finally(() => {
        inFlightPreparedCSSBuilds.delete(context.cacheKey);
    });
    inFlightPreparedCSSBuilds.set(context.cacheKey, task);
    return true;
}
/**
 * Pre-generate and cache CSS from file list.
 *
 * This extracts Tailwind candidates from source files and generates CSS,
 * storing it in the distributed cache for later retrieval during SSR.
 *
 * Should be called after files are fetched but before SSR starts.
 * This is non-blocking and fire-and-forget - errors are logged but not thrown.
 *
 * @param options Pre-generation options
 * @returns Promise that resolves when CSS is generated (or immediately on error)
 */
export async function pregenerateCSSFromFiles(options) {
    const { projectSlug, projectVersion, files, styleProfile, stylesheet, } = options;
    const startTime = performance.now();
    try {
        logger.debug("Starting", {
            projectSlug,
            projectVersion,
            fileCount: files.length,
            hasStylesheet: Boolean(stylesheet),
            styleProfileHash: styleProfile.hash,
        });
        const result = await buildPreparedCSSArtifactFromFiles(options);
        const duration = performance.now() - startTime;
        logger.debug("Complete", {
            projectSlug,
            projectVersion,
            candidateCount: result.candidateCount,
            cssLength: result.css.length,
            cssHash: result.hash,
            fromCache: result.fromCache,
            duration: `${duration.toFixed(2)}ms`,
        });
    }
    catch (error) {
        const duration = performance.now() - startTime;
        logger.warn("Failed", {
            projectSlug,
            error: error instanceof Error ? error.message : String(error),
            duration: `${duration.toFixed(2)}ms`,
        });
    }
}
/**
 * Find stylesheet content from file list using a configured path or defaults.
 */
export function findStylesheetFromFiles(files, stylesheetPath) {
    if (stylesheetPath) {
        let start = 0;
        while (stylesheetPath[start] === "/")
            start++;
        const normalized = ReflectApply(StringPrototypeSlice, stylesheetPath, [start]);
        const file = ReflectApply(ArrayPrototypeFind, files, [
            (f) => f.content &&
                (f.path === normalized ||
                    ReflectApply(StringPrototypeEndsWith, f.path, [`/${normalized}`])),
        ]);
        if (file?.content)
            return file.content;
    }
    return findGlobalStylesheet(files);
}
/**
 * Find the globals.css content from a file list.
 *
 * Searches for common stylesheet file patterns:
 * - globals.css, global.css
 * - styles/globals.css
 * - app/globals.css
 *
 * @param files List of files with content
 * @returns Stylesheet content or undefined if not found
 */
export function findGlobalStylesheet(files) {
    // Anchored to a path-segment boundary so a prefixed filename such as
    // `theme-globals.css` is not mistaken for the project's global stylesheet.
    const stylesheetPatterns = [
        /(^|\/)globals\.css$/,
        /(^|\/)global\.css$/,
        /(^|\/)styles\/globals\.css$/,
        /(^|\/)app\/globals\.css$/,
        /(^|\/)src\/globals\.css$/,
        /(^|\/)src\/styles\/globals\.css$/,
    ];
    for (let index = 0; index < stylesheetPatterns.length; index++) {
        const pattern = stylesheetPatterns[index];
        const file = ReflectApply(ArrayPrototypeFind, files, [
            (f) => f.content && ReflectApply(RegExpPrototypeExec, pattern, [f.path]),
        ]);
        if (file?.content)
            return file.content;
    }
    return undefined;
}
